<script setup lang="ts">
import{computed,ref}from'vue';
import{parityMessages}from'./parity-labels';
import type{Language,RecentState,OpenResult}from'./types';
const props=defineProps<{language:Language;state:RecentState;update:(action:string,payload?:Record<string,unknown>)=>Promise<OpenResult>}>(),emit=defineEmits(['close','open','update']),t=computed(()=>parityMessages[props.language]),busy=ref(false),error=ref('');
async function change(action:string,payload?:Record<string,unknown>){busy.value=true;error.value='';try{const result=await props.update(action,payload);if(result.recent)emit('update',result.recent);else if(result.error)error.value=t.value.failed;}catch{error.value=t.value.failed;}finally{busy.value=false;}}
</script>
<template><div class="modal-shade" @click.self="!busy&&emit('close')"><section class="dialog recent-dialog" role="dialog" aria-modal="true" :aria-label="t.recentProjects"><h2>{{t.recentProjects}}</h2><p>{{t.recentPrivacy}}</p><p v-if="error" role="alert">{{error}}</p><label><input type="checkbox" :disabled="busy" :checked="state.enabled" data-testid="remember-recent" @change="change('rememberRecent',{enabled:($event.target as HTMLInputElement).checked})">{{t.rememberRecent}}</label><ol><li v-for="entry in state.entries" :key="entry.id"><button :disabled="busy" :data-recent-id="entry.id" @click="emit('open',entry.id)"><strong>{{entry.name}}</strong><small>{{entry.parent}} · {{new Date(entry.time).toLocaleString(language==='en'?'en-US':'zh-CN')}}</small></button></li></ol><p v-if="!state.entries.length">{{t.noRecent}}</p><div class="button-row"><button :disabled="busy" data-testid="clear-recent" @click="change('clearRecent')">{{t.clearRecent}}</button><button :disabled="busy" @click="emit('close')">{{t.close}}</button></div></section></div></template>
<style scoped>.recent-dialog{width:min(640px,94vw)}.recent-dialog ol{list-style:none;padding:0;max-height:46vh;overflow:auto}.recent-dialog li button{width:100%;align-items:start;flex-direction:column;margin:4px 0}.recent-dialog small{color:var(--muted)}</style>
